/* @lc app=leetcode id=3881 lang=kotlin */ class Solution { fun fa(x: Int): Long = (1..x).fold(1L) { a, b -> a * b % 1_000_000_007L } fun iv(x: Long): Long = java.math.BigInteger.valueOf(x).modInverse(java.math.BigInteger.valueOf(1_000_000_007L)).toLong() fun countVisiblePeople(n: Int, pos: Int, k: Int): Int = (2L * fa(n - 1) % 1_000_000_007L * iv(fa(k)) % 1_000_000_007L * iv(fa(n - 1 - k)) % 1_000_000_007L).toInt() }